import{z as r,x as l,o as e,c as n,q as t,j as s,D as E,d as A,s as i,S as o}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"Kitamasa 求第 k 项","description":"","frontmatter":{"title":"Kitamasa 求第 k 项","date":"2026-09-27T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/kitamasa.md","filePath":"cs/kitamasa.md","lastUpdated":1791413859000}'),m={name:"cs/kitamasa.md"};function _(d,a,p,f,c,k){const B=l("Mermaid");return e(),n("div",null,[a[2]||(a[2]=t('<h1 id="kitamasa-求第-k-项" tabindex="-1">Kitamasa 求第 k 项 <a class="header-anchor" href="#kitamasa-求第-k-项" aria-label="Permalink to &quot;Kitamasa 求第 k 项&quot;">​</a></h1><div class="epigraph"><p>求线性递推第 $k$ 项不必造 $k$ 行矩阵：把 $x^k$ 对特征多项式取模，余下的系数就是初值的加权表。</p><footer>—— 据 C. M. Fiduccia 的线性递推多项式算法, 1985；算法竞赛社区通称的 Kitamasa 方法</footer></div><p><a href="/cs/berlekamp-massey">上一课</a>把递推式从序列里挖出来；式子到手，下一个问题是第 \\(10^{18}\\) 项。朴素递推 \\(O(k)\\) 出局，矩阵快速幂 \\(O(L^3\\log k)\\) 在 \\(L\\) 上千时也塌。缺口是 <strong>Kitamasa 法</strong>：把指数问题搬进多项式余数世界，\\(O(L^2\\log k)\\)。本课不重讲 BM，只管「拿到递推之后」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>设 \\(a_i=\\sum_{j=1}^{L} c_j a_{i-j}\\)，初值 \\(a_0..a_{L-1}\\) 已知，求 \\(a_k\\bmod p\\)，\\(k\\) 可到 \\(10^{18}\\)。矩阵幂是对的做法但不是快的做法——每步乘一个 \\(L\\times L\\) 矩阵，\\(L=2000\\) 时单步就是 \\(8\\times 10^9\\) 次乘法。本课不写：非齐次项的补常数技巧、同一递推批量多点求值（那是多项式多点求值的地盘）。</p><p><span class="marginnote">术语翻译：特征多项式 \\(f(x)=x^L-\\sum_j c_j x^{L-j}\\)；「对特征多项式取模」就是把 \\(x^L\\) 按 \\(f\\) 的规则拆成低次项之和，与递推式逐字对应。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>核心恒等式一句话：\\(a_k=\\sum_j [x^k\\bmod f(x)]_j\\cdot a_j\\)，余式的系数即权重。三步走——写下 \\(f\\)；把 \\(x\\) 做快速幂，反复平方，每步平方后立刻对 \\(f\\) 取模降次；把余下的系数当成初值的加权表求和。</p>',8)),(e(),s(o,null,{default:E(()=>[i(B,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E8%BE%93%E5%85%A5%E9%80%92%E6%8E%A8%E7%B3%BB%E6%95%B0%E4%B8%8E%E5%89%8D%20L%20%E9%A1%B9%E5%88%9D%E5%80%BC%22%5D%20--%3E%20B%5B%22%E5%86%99%E4%B8%8B%E7%89%B9%E5%BE%81%E5%A4%9A%E9%A1%B9%E5%BC%8F%20f%22%5D%0A%20%20B%20--%3E%20C%5B%22%E5%AF%B9%20x%20%E5%81%9A%E5%BF%AB%E9%80%9F%E5%B9%82%EF%BC%9A%E5%8F%8D%E5%A4%8D%E5%B9%B3%E6%96%B9%22%5D%0A%20%20C%20--%3E%20D%5B%22%E6%AF%8F%E6%AD%A5%E5%B9%B3%E6%96%B9%E5%90%8E%E7%AB%8B%E5%88%BB%E5%AF%B9%20f%20%E5%8F%96%E6%A8%A1%E9%99%8D%E6%AC%A1%22%5D%0A%20%20D%20--%3E%20E%5B%22%E5%BE%97%E5%88%B0%20x%20%E7%9A%84%20k%20%E6%AC%A1%E5%B9%82%E6%A8%A1%20f%20%E7%9A%84%E7%B3%BB%E6%95%B0%E8%A1%A8%22%5D%0A%20%20E%20--%3E%20F%5B%22a%20%E7%9A%84%20k%20%E6%AC%A1%E9%A1%B9%E7%AD%89%E4%BA%8E%E7%B3%BB%E6%95%B0%E5%8A%A0%E6%9D%83%E5%88%9D%E5%80%BC%E4%B9%8B%E5%92%8C%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p>复杂度逐项拆：平方加取模是两次 \\(O(L^2)\\) 多项式乘法，再乘 \\(\\log k\\) 轮。乘法换 <a href="/cs/fft">FFT</a> 一档的 NTT 能再降到 \\(O(L\\log L\\log k)\\)。</p><p><span class="marginnote">数字实例：斐波那契的特征多项式 \\(f(x)=x^2-x-1\\)。逐次取模得 \\(x^5\\bmod f=5x+3\\)，于是 \\(a_5=5a_1+3a_0=5\\times 1+3\\times 0=5\\)——余式系数就是加权初值的账单。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么对 \\(f\\) 取模合法：递推式逐字翻译成多项式语言，正是 \\(x^L\\equiv\\sum_j c_j x^{L-j}\\)（模 \\(f\\)）。于是「按递推移位一步」与「多项式乘 \\(x\\) 后按 \\(f\\) 降次」是同一件事的两种记法；快速幂只是把重复乘法折叠成平方。两个世界同构，指数再大也只在余数世界里走 \\(\\log k\\) 步。</p><p><span class="marginnote">直觉类比：递推像钟表——\\(x\\) 每长一「阶」就得绕回表盘、按 \\(f\\) 的规矩归位。平方后取模相当于把「走 \\(2^t\\) 小时」压缩成看一次快进齿轮；齿数由 \\(f\\) 决定，走再久也只在表盘刻度里转。</span></p>',5)),(e(),s(o,null,{default:E(()=>[i(B,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20M%5B%22%E7%9F%A9%E9%98%B5%E5%BF%AB%E9%80%9F%E5%B9%82%22%5D%20--%3E%20MC%5B%22%E6%AF%8F%E6%AD%A5%20L%20%E7%AB%8B%E6%96%B9%EF%BC%9AL%20%E8%BF%87%E5%8D%83%E5%8D%B3%E5%A1%8C%22%5D%0A%20%20P%5B%22%E5%A4%9A%E9%A1%B9%E5%BC%8F%E5%B9%82%E5%8F%96%E6%A8%A1%22%5D%20--%3E%20PC%5B%22%E6%9C%B4%E7%B4%A0%E4%B9%98%E6%B3%95%E6%AF%8F%E6%AD%A5%20L%20%E5%B9%B3%E6%96%B9%22%5D%0A%20%20P%20--%3E%20F%5B%22%E4%B9%98%E6%B3%95%E6%8D%A2%20NTT%20%E6%AF%8F%E6%AD%A5%20L%20log%20L%22%5D%0A%20%20PC%20--%3E%20S%5B%22L%20%E5%9C%A8%E6%95%B0%E7%99%BE%E9%87%8F%E7%BA%A7%E7%9A%84%E5%B8%B8%E8%A7%84%E6%88%98%E5%9C%BA%22%5D%0A%20%20F%20--%3E%20S2%5B%22L%20%E6%9B%B4%E5%A4%A7%E4%B8%94%E6%A8%A1%E6%95%B0%E5%90%88%E9%80%82%E6%97%B6%E6%8E%A5%E7%AE%A1%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>递推必须已知——常与上一课 BM 配套：先扫序列拿递推，再交给本课算远项。初值至少要够 \\(L\\) 项，缺项时回头检查 BM 报的长度。\\(L\\) 只有 \\(3\\)、\\(4\\) 时直接写矩阵更快更稳，别为省事硬上多项式乘法；\\(L\\) 上千、\\(k\\) 上 \\(10^{18}\\) 才是本课主场。取模数要配得上乘法：NTT 友好模数之外的素数走拆系数卷积或三模数合并。</p><p><span class="marginnote">常见误区：平方后攒着不取模、想最后统一降次——一次平方度数翻倍，两三轮后多项式长度指数爆炸，内存先于正确性出事。错在漏掉「每步必须降次」这条节律。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(a_k\\) 等于 \\(x^k\\bmod f(x)\\) 的系数加权初值，这就是 Kitamasa 恒等式。</li><li>快速幂反复平方、每步对 \\(f\\) 取模，\\(O(L^2\\log k)\\)，乘法换 NTT 再降一档。</li><li>矩阵幂与多项式幂是同一递推的两种代数包装，规模差一个因子 \\(L\\)。</li><li>出处：C. M. Fiduccia, <em>An Efficient Formula for Linear Recurrences</em>, SIAM J. Comput., 1985；算法竞赛社区通称 Kitamasa 方法。</li></ul>',5))])}const x=r(m,[["render",_]]);export{u as __pageData,x as default};
